Read Sheet1 values, track rows where B equals 1, and count A > 0 strictly between the previous and current marker. Write that count into C for marker rows 2–66 and clear C for all other rows in the answer range. Save the workbook with plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

max_row = 66

def is_num(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool)

A = [None] * (max_row + 1)
B = [None] * (max_row + 1)

for r in range(1, max_row + 1):
    A[r] = vws.cell(row=r, column=1).value
    B[r] = vws.cell(row=r, column=2).value

prev_marker = None
marker_rows = []

for r in range(1, max_row + 1):
    if is_num(B[r]) and float(B[r]) == 1.0:
        if prev_marker is None:
            count = 0
        else:
            count = sum(
                1
                for rr in range(prev_marker + 1, r)
                if is_num(A[rr]) and A[rr] > 0
            )

        if 2 <= r <= 66:
            ws.cell(row=r, column=3).value = count

        marker_rows.append(r)
        prev_marker = r
    else:
        if 2 <= r <= 66:
            ws.cell(row=r, column=3).value = None

wb.save(OUT)

print("marker rows:", marker_rows)
print(
    "sample C values:",
    [ws.cell(row=r, column=3).value for r in (6, 10, 15, 22, 24, 33, 36, 40, 60, 63, 66)],
)
